  ('da8fbee8-ca52-482d-970b-bbae24735555', '229cfa8e-83e6-4311-a6a3-eb8fe349009c', $$inleiding: Birgit en Moshaber laten zich adviseren over een hypotheek; rekentool De Hypotheker$$,
   $$bedrijfseconomie-vwo-2022-iii-birgit-en-moshaber-context1.png$$,
   $$Birgit en Moshaber hebben met behulp van hun aankoopmakelaar een koopwoning gevonden en laten zich vervolgens adviseren over een geschikte financieringsvorm. Na invullen van enkele gegevens, waaronder de gewenste looptijd van 30 jaar, toont de rekentool van de hypotheekadviseur De Hypotheker voor twee hypotheekvormen de hypotheekuitgaven, voor en na belastingvoordeel.$$, 'inline'),
  ('1f8c12a6-258b-40bb-bc44-0ce4ce1c12aa', '229cfa8e-83e6-4311-a6a3-eb8fe349009c', $$advertentie woning Ingenhouszstraat 23, € 329.500 k.k., De Hypotheker$$,
   $$bedrijfseconomie-vwo-2022-iii-birgit-en-moshaber-context2.png$$,
   $$Advertentie: foto van een woning, Ingenhouszstraat 23, 6533 NW Nijmegen, € 329.500 k.k.; logo Jazeker. De Hypotheker; Bereken je jaarlast van dit huis.$$, 'inline'),
  ('1a4f5a30-4c60-42ed-b46f-e8a5ba9258f0', '229cfa8e-83e6-4311-a6a3-eb8fe349009c', $$tabel rekentool: annuïteiten- en lineaire hypotheek, hypotheekuitgaven voor en na belastingvoordeel in jaar 1$$,
   $$bedrijfseconomie-vwo-2022-iii-birgit-en-moshaber-context3.png$$,
